tool_input.command:
$p="$env:USERPROFILE\.dsh\profiles\web\cordis.patch.yml"; $lines=Get-Content $p -Encoding utf8
Write-Output "=== standard L291-295 (显示前导空格数) ==="
291..295 | ForEach-Object { $l=$lines[$_-1]; $sp=$l.Length - $l.TrimStart().Length; "L$_ sp=$sp : $($l.TrimStart())" }
Write-Output "=== 找所有 'tool-workflow' 行 ==="
for($i=0;$i -lt $lines.Count;$i++){ if($lines[$i] -match "id: tool-workflow"){ $l=$lines[$i]; $sp=$l.Length-$l.TrimStart().Length; "L$($i+1) sp=$sp" } }

$bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"
$out = node $bin --profile web --dump-config 2>&1
Write-Output "=== 首行 ==="; $out[0]
Write-Output "=== YAML/patch 错误行(含 not found/error) ==="; $out | Select-String -Pattern "not found|error|invalid" -CaseSensitive:$false | Select-Object -First 5 | ForEach-Object { $_.Line }
Write-Output "=== 各 tool-workflow 归属 + disabled 状态 ==="
for($i=0;$i -lt $out.Count;$i++){
  if($out[$i] -match "id: tool-workflow"){
    $owner=""; for($j=$i;$j -ge 0;$j--){ if($out[$j] -match "id: preset-"){ $owner=$out[$j].Trim(); break } }
    $next1 = if($i+1 -lt $out.Count){$out[$i+1].Trim()}else{''}
    $next2 = if($i+2 -lt $out.Count){$out[$i+2].Trim()}else{''}
    $dis = if($next1 -match 'disabled' -or $next2 -match 'disabled'){'DISABLED'}else{'enabled'}
    Write-Output ("dump L{0}: owner=[{1}] -> {2}" -f ($i+1), $owner, $dis)
  }
}

$bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"
$out = node $bin --profile web --dump-config 2>&1
foreach($ln in @(650,1190,1391,1723,2123)){
  Write-Output "=== workflow @ dump L$ln 上下文 ==="
  $out[($ln-1)..([Math]::Min($ln+2,$out.Count-1))] | ForEach-Object { "  $_" }
}

$p="$env:USERPROFILE\.dsh\profiles\web\cordis.patch.yml"; $lines=Get-Content $p -Encoding utf8
Write-Output "=== profile 里全部 tool-workflow 块(含后2行) ==="
for($i=0;$i -lt $lines.Count;$i++){ if($lines[$i] -match "id: tool-workflow"){ "L$($i+1): $($lines[$i].Trim())"; "     +1: $($lines[$i+1].Trim())"; if($lines[$i+2] -match 'disabled'){"     +2: $($lines[$i+2].Trim())"} } }

$bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"
$out = node $bin --profile web --dump-config 2>&1
Write-Output "=== 顶层 workflow L650 上溯找归属包 ==="
for($j=649;$j -ge 0;$j--){ if($out[$j] -match '^# =='){ Write-Output "所属块头(L$($j+1)): $($out[$j])"; break } }
Write-Output "=== 该块头前后几行 ==="
$out[648..654] | ForEach-Object { "  $_" }
